import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create triangular prism
  const prism = createTriangularPrism();
  group.add(prism);

  // Create emissive core inside prism
  const core = createEmissiveCore();
  prism.add(core);

  // Create caustic streak plane
  const caustic = createCausticPlane();
  group.add(caustic);

  // Create rim light (cool directional from behind-left)
  const rimLight = new THREE.DirectionalLight(0x7eb3d4, 1.5);
  rimLight.position.set(-2, 1.5, -1.5);
  group.add(rimLight);

  // Add text content via fontAtlas
  if (ctx.fontAtlas) {
    addTextMeshes(group, ctx);
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && ctx.primitives) {
    config.cinematicPrimitives.forEach(primitive => {
      if (primitive.name === 'depth-rotate' && ctx.primitives['depth-rotate']) {
        ctx.primitives['depth-rotate'](prism, primitive.params);
      }
    });
  }

  // Initialize handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(prism.rotation);
    gsap.killTweensOf(caustic.scale);

    group.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
      if (child.texture) child.texture.dispose();
    });
  };

  return group;
}

function createTriangularPrism() {
  // Equilateral triangle with side 1.2, circumradius R
  const R = 1.2 / Math.sqrt(3);
  const side = 1.2;
  const length = 1.8;
  const z0 = -length / 2;
  const z1 = length / 2;

  // Triangle vertices (front)
  const v0 = new THREE.Vector3(0, R, z0);
  const v1 = new THREE.Vector3(-side / 2, -R / 2, z0);
  const v2 = new THREE.Vector3(side / 2, -R / 2, z0);

  // Triangle vertices (back)
  const v3 = new THREE.Vector3(0, R, z1);
  const v4 = new THREE.Vector3(-side / 2, -R / 2, z1);
  const v5 = new THREE.Vector3(side / 2, -R / 2, z1);

  const geometry = new THREE.BufferGeometry();
  const positions = [
    ...v0.toArray(), ...v1.toArray(), ...v2.toArray(),
    ...v3.toArray(), ...v4.toArray(), ...v5.toArray(),
  ];

  const indices = [
    0, 2, 1,           // front face
    3, 4, 5,           // back face
    0, 1, 4, 0, 4, 3,  // left-top face
    1, 2, 5, 1, 5, 4,  // bottom face
    2, 0, 3, 2, 3, 5,  // right-top face
  ];

  geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  geometry.setIndex(new THREE.BufferAttribute(new Uint32Array(indices), 1));
  geometry.computeVertexNormals();

  const material = new THREE.MeshPhysicalMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    dispersion: 0.18,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color(0xe8ecf2),
    attenuationDistance: 2.5,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.rotation.z = THREE.MathUtils.degToRad(12);
  mesh.rotation.y = THREE.MathUtils.degToRad(20);

  return mesh;
}

function createEmissiveCore() {
  const geometry = new THREE.OctahedronGeometry(0.35, 2);
  const material = new THREE.MeshBasicMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 2.2,
  });
  return new THREE.Mesh(geometry, material);
}

function createCausticPlane() {
  const width = 2.4;
  const height = 0.5;
  const geometry = new THREE.PlaneGeometry(width, height);

  const texture = createCausticTexture();
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    opacity: 0.35,
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.y = -1.1;
  plane.rotation.x = -Math.PI / 2;

  return plane;
}

function createCausticTexture() {
  const width = 256;
  const height = 64;
  const data = new Uint8Array(width * height * 4);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const t = x / width;
      let r, g, b;
      const a = 255;

      if (t < 0.2) {
        // Fade in to #ff2a38
        const blend = t / 0.2;
        r = Math.round(255 * blend);
        g = Math.round(42 * blend);
        b = Math.round(56 * blend);
      } else if (t < 0.5) {
        // Blend #ff2a38 -> #e8ecf2
        const blend = (t - 0.2) / 0.3;
        r = Math.round(255 * (1 - blend) + 232 * blend);
        g = Math.round(42 * (1 - blend) + 236 * blend);
        b = Math.round(56 * (1 - blend) + 242 * blend);
      } else if (t < 0.8) {
        // Blend #e8ecf2 -> #9fb0c4
        const blend = (t - 0.5) / 0.3;
        r = Math.round(232 * (1 - blend) + 159 * blend);
        g = Math.round(236 * (1 - blend) + 176 * blend);
        b = Math.round(242 * (1 - blend) + 196 * blend);
      } else {
        // Solid #9fb0c4
        r = 159;
        g = 176;
        b = 196;
      }

      const idx = (y * width + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = a;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}

function addTextMeshes(group, ctx) {
  const textConfigs = [
    {
      text: "Light, machined.",
      position: { x: 0, y: -1.75, z: 0.1 },
      fontSize: 68,
      fontWeight: 600,
      family: 'Lora',
      color: 0xe8ecf2,
      letterSpacing: -0.005,
      align: 'center',
    },
    {
      text: "SAPPHIRE OVER DIAL / ZERO DISTORTION",
      position: { x: 0, y: -2.25, z: 0.1 },
      fontSize: 18,
      fontWeight: 400,
      family: 'JetBrains Mono',
      color: 0xe8ecf2,
      letterSpacing: 0.08,
      align: 'center',
    },
  ];

  textConfigs.forEach(config => {
    let mesh;

    if (typeof ctx.fontAtlas.createText === 'function') {
      mesh = ctx.fontAtlas.createText(config.text, config);
    } else if (typeof ctx.fontAtlas === 'function') {
      mesh = ctx.fontAtlas(config.text, config);
    }

    if (mesh) {
      mesh.position.set(config.position.x, config.position.y, config.position.z);
      group.add(mesh);
    }
  });
}
